-- DB update 2026_09_10_02 -> 2026_09_10_03
-- Arcane Mage rework, Phase 2 (docs/arcane-mage-rework-design.md), Rows 0-3.
--
-- Data-only talents per .claude/skills/class-rework/SKILL.md Phase 2: Alacrity, Arcane
-- Meditation, Arcane Stability (Row 0); Magic Absorption, Arcane Subtlety, Spell Impact
-- (Row 1); Arcane Concentration, Magic Attunement, Student of the Mind, Focus Magic (Row 2);
-- Arcane Shielding, Improved Counterspell, Arcane Resonance-shell (Row 3). Spellblade (0,3)
-- is also a shell only. See each spell's `notes` in apps/dbc-tools/source/spells/mage.csv /
-- mage_talents.csv for its own rationale, and the design doc's "Phase 2/3 Implementation
-- Notes" section for the full slot-mapping table and the Deferred-to-Phase-3 list.
--
-- Talent tab (81/Arcane) slot reuse: 27 of the tree's 30 slots repoint an existing stock
-- Talent.dbc id (SpellRank_* repointed to new/edited spells, TierID/ColumnIndex repointed to
-- the new layout - same discipline as the Frost Mage rework's own migrations). Only 3 new
-- talent ids are minted from the reserved block (60000-60799) for the whole tree; this batch
-- uses one of them (60007, Spellblade). talent 421 (Arcane Instability)'s depends_on is
-- zeroed - it pointed at talent id 86 (Presence of Mind), which left the tree entirely this
-- rework (moved to baseline); matches Frost's own precedent of zeroing stale prerequisites
-- pending the user specifying the real chain, rather than guessing at one.
--
-- Produced by `python3 apps/dbc-tools/generate.py` from apps/dbc-tools/source/{spells,talents}/*,
-- then hand-extracted to just the rows this batch owns (same discipline as Phase 1's own
-- migration and the Frost Mage rework's precedent).
--
-- Regenerate/extend via: python3 apps/dbc-tools/generate.py (see apps/dbc-tools/README.md)

DELETE FROM `spell_dbc` WHERE `ID` IN (11210, 11213, 11222, 11237, 11242, 11247, 11252, 11255, 12463, 12464, 12467, 12469, 12574, 12575, 12592, 12598, 12605, 12606, 12839, 12840, 18462, 18463, 18464, 28574, 29441, 29444, 44397, 44398, 44399, 54646, 54658, 200071, 200072, 200073, 200074, 200075, 200076);

DELETE FROM `talent_dbc` WHERE `ID` IN (74, 75, 80, 81, 82, 85, 421, 1650);
